s = s.replace(/"'^index .*$/gm, '"'').replace(/"'^(diff --git a'"\\/src\\/App\\.tsx b\\/src\\/App\\.tsx)"'$/gm, '"'\\"'$1'"');
fs.writeFileSync('/tmp/theme-noindex.patch', s);
\"
git apply --verbose /tmp/theme-noindex.patch"

/bin/bash -lc "node -e \"
const fs = require('fs');
const p = 'src/ThemeToggle.tsx';
const lines = fs.readFileSync(p, 'utf8').split('\\n');
const i = lines.findIndex((line) => line.includes('onUpdate='));
lines[i] = '      onUpdate={(nextTheme) => setTheme(nextTheme as Theme)}';
fs.writeFileSync(p, lines.join('\\n'));
\"
cat src/ThemeToggle.tsx"

